package com.deepoove.poi.render;

import java.lang.reflect.Array;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;

import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.apache.poi.xwpf.usermodel.XWPFRun;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

public class RenderContextgetContainer_XWPFParagraphgetBodyFikaTest {

    @Test
    public void testGetContainer() throws Exception {
        XWPFDocument document = new XWPFDocument();
        XWPFParagraph paragraph = document.createParagraph();
        XWPFRun run = paragraph.createRun();

        Class<?> clazz = Class.forName("com.deepoove.poi.render.RenderContext");
        Constructor<?>[] constructors = clazz.getDeclaredConstructors();

        Object instance = tryInstantiate(clazz, constructors, document, paragraph, run, false, 0);
        if (instance == null) {
            instance = tryInstantiate(clazz, constructors, document, paragraph, run, false, 1);
        }
        if (instance == null) {
            instance = tryInstantiate(clazz, constructors, document, paragraph, run, true, 0);
        }
        if (instance == null) {
            instance = tryInstantiate(clazz, constructors, document, paragraph, run, true, 1);
        }
        if (instance == null) {
            instance = tryInstantiate(clazz, constructors, document, paragraph, run, true, 2);
        }

        for (Class<?> current = clazz; current != null; current = current.getSuperclass()) {
            for (Field field : current.getDeclaredFields()) {
                boolean isRunField = XWPFRun.class.equals(field.getType())
                        || (field.getType().isAssignableFrom(XWPFRun.class)
                                && field.getName().toLowerCase().contains("run"));
                if (isRunField) {
                    field.setAccessible(true);
                    try {
                        field.set(instance, run);
                    } catch (Throwable ignored) {
                    }
                }
            }
        }

        Method method;
        try {
            method = clazz.getMethod("getContainer");
        } catch (NoSuchMethodException e) {
            method = clazz.getDeclaredMethod("getContainer");
        }
        method.setAccessible(true);
        method.invoke(instance);
    }

    private Object tryInstantiate(Class<?> clazz, Constructor<?>[] constructors, XWPFDocument document,
            XWPFParagraph paragraph, XWPFRun run, boolean useMocks, int runMode) {
        for (Constructor<?> constructor : constructors) {
            Class<?>[] parameterTypes = constructor.getParameterTypes();
            if (runScore(parameterTypes, runMode) < 0) {
                continue;
            }
            Object[] args = buildArgs(parameterTypes, clazz, document, paragraph, run, useMocks, runMode);
            constructor.setAccessible(true);
            try {
                return constructor.newInstance(args);
            } catch (Throwable ignored) {
            }
        }
        return null;
    }

    private int runScore(Class<?>[] parameterTypes, int runMode) {
        boolean exact = false;
        boolean assignable = false;
        for (Class<?> pt : parameterTypes) {
            if (pt == XWPFRun.class) {
                exact = true;
            }
            if (pt != Object.class && pt.isAssignableFrom(XWPFRun.class)) {
                assignable = true;
            }
        }
        if (runMode == 0) {
            return exact ? 0 : -1;
        }
        if (runMode == 1) {
            return (!exact && assignable) ? 1 : -1;
        }
        return 2;
    }

    private Object[] buildArgs(Class<?>[] parameterTypes, Class<?> clazz, XWPFDocument document,
            XWPFParagraph paragraph, XWPFRun run, boolean useMocks, int runMode) {
        Object[] args = new Object[parameterTypes.length];
        boolean runAssigned = false;
        for (int i = 0; i < parameterTypes.length; i++) {
            Class<?> pt = parameterTypes[i];

            if (!runAssigned && runMode == 0 && pt == XWPFRun.class) {
                args[i] = run;
                runAssigned = true;
                continue;
            }
            if (!runAssigned && runMode >= 1 && pt != Object.class && pt.isAssignableFrom(XWPFRun.class)) {
                args[i] = run;
                runAssigned = true;
                continue;
            }
            if (pt.isArray() && pt.getComponentType() == XWPFRun.class) {
                args[i] = new XWPFRun[] { run };
                continue;
            }
            if (pt == Object.class) {
                args[i] = useMocks ? new Object() : null;
                continue;
            }
            if (pt == XWPFDocument.class || pt.isAssignableFrom(XWPFDocument.class)) {
                args[i] = document;
                continue;
            }
            if (pt == XWPFParagraph.class || pt.isAssignableFrom(XWPFParagraph.class)) {
                args[i] = paragraph;
                continue;
            }
            if (pt == Class.class) {
                args[i] = clazz;
                continue;
            }
            if (pt == String.class) {
                args[i] = "test";
                continue;
            }
            if (pt == clazz) {
                args[i] = null;
                continue;
            }
            if (pt.isPrimitive()) {
                args[i] = defaultValue(pt);
                continue;
            }
            if (useMocks) {
                args[i] = createMockOrInstance(pt);
            } else {
                args[i] = null;
            }
        }
        return args;
    }

    private Object createMockOrInstance(Class<?> pt) {
        if (pt.isArray()) {
            return Array.newInstance(pt.getComponentType(), 0);
        }
        try {
            Constructor<?> noArg = pt.getDeclaredConstructor();
            noArg.setAccessible(true);
            return noArg.newInstance();
        } catch (Throwable ignored) {
        }
        try {
            return Mockito.mock(pt);
        } catch (Throwable ignored) {
            return null;
        }
    }

    private Object defaultValue(Class<?> pt) {
        if (pt == boolean.class) {
            return false;
        }
        if (pt == byte.class) {
            return (byte) 0;
        }
        if (pt == short.class) {
            return (short) 0;
        }
        if (pt == int.class) {
            return 0;
        }
        if (pt == long.class) {
            return 0L;
        }
        if (pt == float.class) {
            return 0.0f;
        }
        if (pt == double.class) {
            return 0.0d;
        }
        if (pt == char.class) {
            return '�';
        }
        return null;
    }
}

