            List<XWPFParagraph> paragraphs = ((List<XWPFParagraph>) (ReflectionUtils.getValue("paragraphs", cell)));
            paragraphs.remove(indexOf);
            cell.getCTTc().removeP(indexOf);
        }
        bodyElements.remove(pos);
