import org.apache.commons.lang3.tuple.Pair;
import org.junit.jupiter.api.Test;
import java.util.HashMap;
import java.util.Map;

public class ConfiguretoString_PairgetRightFikaTest {

    @Test
    public void testToStringInvokesPairGetRight() {
        // Create a mock-like Configure object with minimal required fields
        Configure configure = new Configure();

        // Set up the iterable Pair that will be accessed in toString()
        Pair<String, String> testPair = Pair.of("leftValue", "rightValue");
        configure.iterable = testPair;

        // Set other required fields to avoid NPE
        configure.gramerPrefix = "[";
        configure.gramerSuffix = "]";
        configure.grammerRegex = ".*";
        configure.handler = new Object();

        // Initialize collections to avoid NPE in forEach loops
        configure.DEFAULT_POLICYS = new HashMap<>();
        configure.CUSTOM_POLICYS = new HashMap<>();
        configure.DEFAULT_CHART_POLICYS = new HashMap<>();
        configure.DEFAULT_TEMPLATE_POLICYS = new HashMap<>();
        configure.spELFunction = new HashMap<>();

        // Execute toString() which should invoke iterable.getRight()
        configure.toString();
    }

