            try {
                if (parameterTypes.length == 1 && parameterTypes[0].isAssignableFrom(block.getClass())) {
                    constructor.setAccessible(true);
                    return constructor.newInstance(block);
                }
                if (parameterTypes.length == 2 && parameterTypes[0].isAssignableFrom(block.getClass())) {
                    constructor.setAccessible(true);
                    try {
                        return constructor.newInstance(block, document);
                    } catch (Exception ignored) {
                        return constructor.newInstance(block, null);
                    }
                }
            } catch (Exception ignored) {
            }
        }
        throw new IllegalStateException("Unable to create XWPFSDTContent");
    }

    private static Object createContainer(Class<?> containerClass, Class<?> sdtContentClass, Object sdtContent) throws Exception {
        for (Constructor<?> constructor : containerClass.getDeclaredConstructors()) {
            Class<?>[] parameterTypes = constructor.getParameterTypes();
            try {
                if (parameterTypes.length == 1 && parameterTypes[0].isAssignableFrom(sdtContentClass)) {
                    constructor.setAccessible(true);
                    return constructor.newInstance(sdtContent);
                }
            } catch (Exception ignored) {
            }
        }
        try {
            Constructor<?> noArg = containerClass.getDeclaredConstructor();
            noArg.setAccessible(true);
            return noArg.newInstance();
        } catch (Exception ignored) {
        }
        Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
        Field theUnsafe = unsafeClass.getDeclaredField("theUnsafe");
        theUnsafe.setAccessible(true);
        Object unsafe = theUnsafe.get(null);
        Method allocateInstance = unsafeClass.getMethod("allocateInstance", Class.class);
        return allocateInstance.invoke(unsafe, containerClass);
    }

    private static Field findField(Class<?> clazz, String name) throws NoSuchFieldException {
        Class<?> current = clazz;
        while (current != null) {
            try {
                return current.getDeclaredField(name);
            } catch (NoSuchFieldException ignored) {
                current = current.getSuperclass();
            }
        }
        throw new NoSuchFieldException(name);
    }
}

