public class XDDFOfPieChartDataaddSeries_CTOfPieChartaddNewSerFikaTest {

    @Test
    public void testAddSeriesInvokesCTOfPieChartAddNewSer() {
        XSSFWorkbook workbook = new XSSFWorkbook();
        XSSFSheet sheet = workbook.createSheet();
        XSSFRow row = sheet.createRow(0);
        row.createCell(0).setCellValue("Category");
        row.createCell(1).setCellValue(1.0);

        XSSFDrawing drawing = sheet.createDrawingPatriarch();
        XSSFClientAnchor anchor = drawing.createAnchor(0, 0, 0, 0, 0, 0, 5, 5);
        XSSFChart chart = drawing.createChart(anchor);

        XDDFOfPieChartData data = new XDDFOfPieChartData(chart);
        XDDFDataSource<?> category = XDDFDataSourcesFactory.fromStringCellRange(
                chart, new CellRangeAddress(0, 0, 0, 0));
        XDDFNumericalDataSource<? extends Number> values = XDDFDataSourcesFactory.fromNumericCellRange(
                chart, new CellRangeAddress(0, 0, 1, 1));

        data.addSeries(category, values);
    }
}

