import java.io.ByteArrayOutputStream;

import static org.mockito.Mockito.when;

public class NiceXWPFDocumentaddChartData_XWPFChartsetWorkbookFikaTest {

    @Test
    public void testAddChartData() throws Exception {
        // Create a minimal XSSFWorkbook for the chart
        XSSFWorkbook workbook = new XSSFWorkbook();
        workbook.createSheet().createRow(0).createCell(0).setCellValue("Test");

