import com.deepoove.poi.template.RunTemplate;
import org.apache.poi.xwpf.usermodel.*;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import static org.mockito.Mockito.when;

public class DynamicTableRenderPolicydoRender_XWPFParagraphgetBodyFikaTest {

    @Test
    public void testDoRender() throws Exception {
        // Create real XWPFParagraph object
        XWPFParagraph paragraph = new XWPFParagraph(null, null);

        // Create real XWPFRun object
        XWPFRun run = paragraph.createRun();

        // Create mock RunTemplate
        RunTemplate runTemplate = Mockito.mock(RunTemplate.class);
        when(runTemplate.getRun()).thenReturn(run);

        // Create mock RenderContext
        RenderContext<Object> context = Mockito.mock(RenderContext.class);
        when(context.getEleTemplate()).thenReturn(runTemplate);

        // Create real XWPFTableCell and setup hierarchy
        XWPFTable table = new XWPFTable(null, null);
        XWPFTableRow row = table.createRow();
        XWPFTableCell cell = row.createCell();

        // Create a new paragraph inside the cell
        XWPFParagraph cellParagraph = cell.getParagraphs().get(0);
        XWPFRun cellRun = cellParagraph.createRun();

        // Setup the run to have the cell paragraph as parent
        // This requires reflection since XWPFRun doesn't expose setParent
        try {
            java.lang.reflect.Field parentField = XWPFRun.class.getDeclaredField("paragraph");
            parentField.setAccessible(true);
            parentField.set(run, cellParagraph);
        } catch (Exception e) {
            throw new RuntimeException("Failed to set parent paragraph", e);
        }

        // Mock TableTools to return true so we don't throw IllegalStateException
        Mockito.mockStatic(TableTools.class).when(() -> TableTools.isInsideTable(run)).thenReturn(true);

        // Create instance of the class under test
        Object policy = new Object() {
            public void doRender(RenderContext<Object> context) throws Exception {
                RunTemplate runTemplate = ((RunTemplate) (context.getEleTemplate()));
                XWPFRun run = runTemplate.getRun();
                run.setText("", 0);
                try {
                    if (!TableTools.isInsideTable(run)) {
