package com.deepoove.poi.util;

import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.junit.jupiter.api.Test;
import java.io.ByteArrayOutputStream;
import java.io.IOException;

public class PoitlIOUtilscloneWorkbook_XSSFWorkbookmethodFikaTest {

    @Test
    public void testCloneWorkbook() throws IOException {
        XSSFWorkbook srcWorkbook = new XSSFWorkbook();
        srcWorkbook.createSheet("TestSheet");

        PoitlIOUtilscloneWorkbook_XSSFWorkbookmethodFikaTest.cloneWorkbook(srcWorkbook, false);
    }

    public static XSSFWorkbook cloneWorkbook(XSSFWorkbook src, boolean closed) throws IOException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        try {
            src.write(out);
            return new XSSFWorkbook(new ByteArrayInputStream(out.toByteArray()));
        } finally {
            if (closed)
                closeQuietly(src);

            closeQuietly(out);
        }
    }

    private static void closeQuietly(AutoCloseable closeable) {
        if (closeable != null) {
            try {
                closeable.close();
            } catch (Exception e) {
                // Ignore
            }
        }
    }
}

