import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.Arrays;

import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.apache.poi.xwpf.usermodel.XWPFRun;
import org.junit.jupiter.api.Test;

public class PaginationRenderPolicydoRender_XWPFRunaddBreakFikaTest {

    @Test
    public void doRenderShouldInvokeXWPFRunAddBreak() throws Exception {
        XWPFDocument document = new XWPFDocument();
        XWPFParagraph paragraph = document.createParagraph();
        XWPFRun run = paragraph.createRun();
        run.setText("{{pagination}}");

        Object policy = createPolicy();
        Method doRender = findDoRender(policy.getClass());
        Class<?> contextClass = doRender.getParameterTypes()[0];
        Object context = createRenderContext(run, Boolean.TRUE, contextClass);

        doRender.invoke(policy, context);
    }

    private static Object createPolicy() throws Exception {
        Class<?> clazz = Class.forName("com.deepoove.poi.plugin.pagination.PaginationRenderPolicy");

        try {
            Constructor<?> ctor = clazz.getDeclaredConstructor();
            ctor.setAccessible(true);
            return ctor.newInstance();
        } catch (Throwable ignored) {
        }

        Constructor<?>[] ctors = clazz.getDeclaredConstructors();
        Arrays.sort(ctors, (a, b) -> Integer.compare(b.getParameterCount(), a.getParameterCount()));

        for (Constructor<?> ctor : ctors) {
            Class<?>[] types = ctor.getParameterTypes();
            Object[] args = new Object[types.length];
            for (int i = 0; i < types.length; i++) {
                args[i] = defaultValue(types[i]);
            }

            try {
                ctor.setAccessible(true);
                return ctor.newInstance(args);
            } catch (Throwable ignored) {
            }
        }

        Object allocated = allocateInstance(clazz);
        if (allocated != null) {
            return allocated;
        }

        throw new IllegalStateException("Unable to create policy");
    }

    private static Method findDoRender(Class<?> clazz) throws Exception {
        Method fallback = null;
        Class<?> c = clazz;

        while (c != null) {
            for (Method m : c.getDeclaredMethods()) {
                if (m.getName().equals("doRender") && m.getParameterCount() == 1) {
                    if (m.getParameterTypes()[0].getSimpleName().contains("RenderContext")) {
                        try {
                            m.setAccessible(true);
                        } catch (Throwable ignored) {
                        }
                        return m;
                    }
                    if (fallback == null) {
                        fallback = m;
                    }
                }
            }
            c = c.getSuperclass();
        }

        if (fallback != null) {
            try {
                fallback.setAccessible(true);
            } catch (Throwable ignored) {
            }
            return fallback;
        }

        throw new NoSuchMethodException("doRender");
    }

    private static Object createRenderContext(XWPFRun run, Boolean data, Class<?> contextClass) {
        String tagName = "{{pagination}}";
        Object context = null;

        Constructor<?>[] ctors = contextClass.getDeclaredConstructors();
        Arrays.sort(ctors, (a, b) -> Integer.compare(scoreConstructor(b), scoreConstructor(a)));

        for (Constructor<?> ctor : ctors) {
            Object[] args = buildConstructorArgs(ctor, tagName, run, data);
            if (args == null) {
                continue;
            }

            try {
                ctor.setAccessible(true);
                context = ctor.newInstance(args);
                if (context != null) {
                    break;
                }
            } catch (Throwable ignored) {
            }
        }

        if (context == null) {
            context = allocateInstance(contextClass);
        }

        if (context != null) {
            setProperty(contextClass, context, "run", "setRun", run);
            setProperty(contextClass, context, "xwpfRun", "setXWPFRun", run);
            setProperty(contextClass, context, "data", "setData", data);
            setProperty(contextClass, context, "value", "setValue", data);
            setProperty(contextClass, context, "tagName", "setTagName", tagName);
            setProperty(contextClass, context, "tag", "setTag", tagName);
            setProperty(contextClass, context, "isClearTemplate", "setClearTemplate", Boolean.TRUE);
            setProperty(contextClass, context, "clearTemplate", "setClearTemplate", Boolean.TRUE);
        }

        return context;
    }

    private static int scoreConstructor(Constructor<?> ctor) {
        int score = 0;

        for (Class<?> type : ctor.getParameterTypes()) {
            if (type == XWPFRun.class) {
                score += 100;
            } else if (type == Object.class || type == Boolean.class || type == boolean.class) {
                score += 90;
            } else if (type == String.class) {
                score += 10;
            } else if (type.isPrimitive()) {
                score += 1;
            } else {
                score += 50;
            }
        }

        return score;
    }

    private static Object[] buildConstructorArgs(Constructor<?> ctor, String tagName, XWPFRun run, Boolean data) {
        Class<?>[] types = ctor.getParameterTypes();
        Object[] args = new Object[types.length];

        for (int i = 0; i < types.length; i++) {
            Class<?> type = types[i];

