import org.mockito.Mockito;

import java.math.BigInteger;

public class HelperrenderComment_CTMarkupsetIdFikaTest {

    @Test
    public void testRenderComment() throws Exception {
        // Create real run with mocked parent paragraph
        XWPFRun run = Mockito.mock(XWPFRun.class);
        XWPFParagraph paragraph = Mockito.mock(XWPFParagraph.class);
        Mockito.when(run.getParent()).thenReturn(paragraph);

        // Create NiceXWPFDocument mock
        NiceXWPFDocument document = Mockito.mock(NiceXWPFDocument.class);
        Mockito.when(paragraph.getDocument()).thenReturn(document);

        // Create XWPFComments mock
        XWPFComments comments = Mockito.mock(XWPFComments.class);
        Mockito.when(document.createComments()).thenReturn(comments);

        // Create XWPFComment mock with CTComment
        XWPFComment comment = Mockito.mock(XWPFComment.class);
        org.openxmlformats.schemas.wordprocessingml.x2006.main.CTComment ctComment = 
            org.openxmlformats.schemas.wordprocessingml.x2006.main.CTComment.Factory.newInstance();
        Mockito.when(comment.getCtComment()).thenReturn(ctComment);
        Mockito.when(comments.createComment(Mockito.any(BigInteger.class))).thenReturn(comment);

        // Mock NextIDUtils.getCommentMaxId to return BigInteger.ZERO
        Mockito.mockStatic(com.deepoove.poi.util.NextIDUtils.class).when(
            () -> com.deepoove.poi.util.NextIDUtils.getCommentMaxId(comments)
        ).thenReturn(BigInteger.ZERO);

        // Create CommentRenderData with CommentContent
        CommentRenderData data = new CommentRenderData();
        CommentContent commentContent = new CommentContent();
        commentContent.setAuthor("Test Author");
        commentContent.setDate("2024-01-01");
        commentContent.setInitials("TA");
        commentContent.setContent(new com.deepoove.poi.data.TextRenderData());
        data.setCommentContent(commentContent);
        data.setContents(new com.deepoove.poi.data.ParagraphRenderData());

        // Mock ParagraphUtils.getRunPos to return 0
        Mockito.mockStatic(com.deepoove.poi.util.ParagraphUtils.class).when(
            () -> com.deepoove.poi.util.ParagraphUtils.getRunPos(run)
        ).thenReturn(0);

        // Create XWPFParagraphWrapper that will trigger CTMarkup.setId
        XWPFParagraphWrapper parentContext = new XWPFParagraphWrapper(paragraph);

        // Mock the static method call in renderParagraph
        Mockito.mockStatic(com.deepoove.poi.plugin.comment.Helper.class).when(
            () -> com.deepoove.poi.plugin.comment.Helper.renderParagraph(
                Mockito.any(XWPFRun.class), 
                Mockito.any(com.deepoove.poi.data.ParagraphRenderData.class))
        ).thenAnswer(invocation -> null);

        // Mock the static method call in renderDocument
        Mockito.mockStatic(com.deepoove.poi.plugin.comment.Helper.class).when(
            () -> com.deepoove.poi.plugin.comment.Helper.renderDocument(
                Mockito.any(XWPFRun.class), 
                Mockito.any(com.deepoove.poi.data.TextRenderData.class))
        ).thenAnswer(invocation -> null);

        // Execute the method under test
        Helper.renderComment(run, data);
    }
}

