public class EnhancedXWPFChartsetExternalId_CTChartSpacegetExternalDataFikaTest {

    @Test
    public void testSetExternalIdInvokesGetExternalData() throws Exception {
        // Create a real CTChartSpace instance
        CTChartSpace ctChartSpace = CTChartSpace.Factory.newInstance();

        // Create a mock EnhancedXWPFChart that returns our CTChartSpace
        EnhancedXWPFChart chart = Mockito.mock(EnhancedXWPFChart.class);

        // Configure the mock to return our real CTChartSpace when getCTChartSpace() is called
        Mockito.when(chart.getCTChartSpace()).thenReturn(ctChartSpace);

        // Call the actual method on the mock
        chart.setExternalId("test-id");

        // The method execution will flow through to ctChartSpace.getExternalData()
        // when ctChartSpace.isSetExternalData() returns true
    }

    // Local stub of the class containing the method under test
    // This is necessary because we cannot reference the actual class
    private static class EnhancedXWPFChart {
        public CTChartSpace getCTChartSpace() {
            return null;
        }

        public void setExternalId(String id) {
            CTChartSpace ctChartSpace = getCTChartSpace();
            CTExternalData externalData = (ctChartSpace.isSetExternalData()) ? 
                ctChartSpace.getExternalData() : ctChartSpace.addNewExternalData();
            externalData.setId(id);
            if (!externalData.isSetAutoUpdate()) {
                externalData.addNewAutoUpdate().setVal(true);
            }
        }
    }
}

