    super(category, values);
    this.series = series;
}

protected Series(CTPieSer series, CTAxDataSource category, CTNumDataSource values) {
    super(XDDFDataSourcesFactory.fromDataSource(category), XDDFDataSourcesFactory.fromDataSource(values));
    this.series = series;
}

