package com.deepoove.poi.plugin.table;

import com.deepoove.poi.XWPFTemplate;
import com.deepoove.poi.config.Configure;
import com.deepoove.poi.policy.RenderPolicy;
import com.deepoove.poi.template.ElementTemplate;
import com.deepoove.poi.template.run.RunTemplate;
import org.apache.poi.xwpf.usermodel.*;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.util.ArrayList;
import java.util.List;

public class MultipleRowTableRenderPolicyrender_XWPFTableRowmethodFikaTest {

    @Test
    public void testRenderInvokesXWPFTableRowConstructor() throws Exception {
        // Create minimal real objects for the call path
        XWPFDocument document = new XWPFDocument();
        XWPFTable table = document.createTable(3, 2);
        XWPFTableRow row = table.getRow(1);
        XWPFTableCell cell = row.getCell(0);

        XWPFParagraph paragraph = cell.addParagraph();
        XWPFRun run = paragraph.createRun();
        run.setText("{{#items}}");

        // Create template with minimal configuration
        Configure config = Configure.builder().build();
        XWPFTemplate template = Mockito.spy(XWPFTemplate.create(document, config));

        // Create RunTemplate that points to our run
        RunTemplate runTemplate = Mockito.mock(RunTemplate.class);
        Mockito.when(runTemplate.getRun()).thenReturn(run);
        Mockito.when(runTemplate.getTagName()).thenReturn("items");

        // Create test data
        List<String> data = new ArrayList<>();
        data.add("Item 1");
        data.add("Item 2");

        // Create policy instance
        RenderPolicy policy = new MultipleRowTableRenderPolicy();

        // Execute render method - this should invoke XWPFTableRow constructor
        policy.render(runTemplate, data, template);

        // Clean up
        document.close();
    }
}

