public class AttachmentRenderPolicydoRender_InputSourcemethodFikaTest {

    @Test
    public void testDoRender() throws Exception {
        // Create real objects for the method under test
        AttachmentRenderPolicy policy = new AttachmentRenderPolicy();

        // Mock the RenderContext and its dependencies
        RenderContext<AttachmentRenderData> context = Mockito.mock(RenderContext.class);
        NiceXWPFDocument doc = Mockito.mock(NiceXWPFDocument.class);
        XWPFRun run = Mockito.mock(XWPFRun.class);
        CTR ctr = Mockito.mock(CTR.class);
        AttachmentRenderData data = Mockito.mock(AttachmentRenderData.class);

        // Setup the context mock to return required objects
        Mockito.when(context.getXWPFDocument()).thenReturn(doc);
        Mockito.when(context.getRun()).thenReturn(run);
        Mockito.when(context.getData()).thenReturn(data);
        Mockito.when(run.getCTR()).thenReturn(ctr);

        // Setup attachment data
        byte[] attachmentData = "fake attachment content".getBytes();
        Mockito.when(data.readAttachmentData()).thenReturn(attachmentData);
        Mockito.when(data.getFileType()).thenReturn(AttachmentType.ARCHIVE);

        // Setup picture data
        byte[] imageData = new byte[]{0x00, 0x01, 0x02, 0x03};
        PictureRenderData icon = Pictures.ofBytes(imageData, PictureType.PNG).size(64, 64).create();
        Mockito.when(data.getIcon()).thenReturn(null);

        // Setup document methods to return IDs
        Mockito.when(doc.addPictureData(Mockito.any(byte[].class), Mockito.anyInt())).thenReturn("rId1");
        Mockito.when(doc.addEmbeddData(Mockito.any(byte[].class), Mockito.anyString(), Mockito.anyString()))
               .thenReturn("rId2");

        // Reset the static flag to ensure shape type XML is generated
        resetHaveShapeTypeFlag(policy);

        // Execute the method - this will trigger InputSource constructor with StringReader
        policy.doRender(context);
    }

    private void resetHaveShapeTypeFlag(AttachmentRenderPolicy policy) throws Exception {
        // Use reflection to reset the haveShapeType flag
