public List<XWPFStructuredDocumentTag> getSDTs() {
    if (null != sdts) {
        return sdts;
    }
    sdts = new ArrayList<>();
    long count = paragraph.getIRuns().stream().filter(r -> r instanceof XWPFSDT).count();
    if (0 == count) {
        return sdts;
    }
    CTP ctp = paragraph.getCTP();
    XmlCursor c = ctp.newCursor();
    try {
        c.selectPath("child::*");
        while (c.toNextSelection()) {
            XmlObject o = c.getObject();
            if (o instanceof CTSdtBlock) {
                XWPFStructuredDocumentTag cc = // PATH: Test should invoke the next XWPFParagraph.getBody(...) [step in execution path]
                new XWPFStructuredDocumentTag(((CTSdtBlock) (o)), paragraph.getBody());
                sdts.add(cc);
            }
            if (o instanceof CTSdtRun) {
                XWPFStructuredDocumentTag cc = new XWPFStructuredDocumentTag(((CTSdtRun) (o)), paragraph.getBody());
                sdts.add(cc);
            }
        } 
    } finally {
        c.dispose();
    }
    return sdts;
}

