package com.deepoove.poi.util;

import org.apache.poi.xwpf.usermodel.XWPFTable;
import org.apache.poi.xwpf.usermodel.TableWidthType;
import org.apache.poi.xwpf.usermodel.XWPFTable.XWPFBorderType;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import com.deepoove.poi.util.StyleUtils;
import com.deepoove.poi.util.TableStyle;
import com.deepoove.poi.util.TableTools;
import com.deepoove.poi.util.UnitUtils;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTbl;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblPr;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblWidth;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.STTblWidth;
import java.math.BigInteger;

public class StyleUtilsstyleTable_CTTblWidthsetTypeFikaTest {

    @Test
    public void testStyleTable() throws Exception {
        TableStyle tableStyle = Mockito.mock(TableStyle.class);
        Mockito.when(tableStyle.getWidth()).thenReturn(100);
        Mockito.when(tableStyle.getColWidths()).thenReturn(new double[]{50.0, 50.0});
        Mockito.when(tableStyle.getLeftBorder()).thenReturn(new TableTools.Border());
        Mockito.when(tableStyle.getRightBorder()).thenReturn(new TableTools.Border());
        Mockito.when(tableStyle.getTopBorder()).thenReturn(new TableTools.Border());
        Mockito.when(tableStyle.getBottomBorder()).thenReturn(new TableTools.Border());
        Mockito.when(tableStyle.getInsideHBorder()).thenReturn(new TableTools.Border());
        Mockito.when(tableStyle.getInsideVBorder()).thenReturn(new TableTools.Border());
        Mockito.when(tableStyle.getAlign()).thenReturn(TableWidthType.AUTO);
        Mockito.when(tableStyle.getTopCellMargin()).thenReturn(10);
        Mockito.when(tableStyle.getLeftCellMargin()).thenReturn(10);
        Mockito.when(tableStyle.getBottomCellMargin()).thenReturn(10);
        Mockito.when(tableStyle.getRightCellMargin()).thenReturn(10);
        Mockito.when(tableStyle.getIndentation()).thenReturn(2.5);

        XWPFTable table = Mockito.mock(XWPFTable.class);
        CTTbl ctTbl = Mockito.mock(CTTbl.class);
        CTTblPr tPr = Mockito.mock(CTTblPr.class);
        CTTblWidth tw = Mockito.mock(CTTblWidth.class);

        Mockito.when(table.getCTTbl()).thenReturn(ctTbl);
        Mockito.when(ctTbl.getTblPr()).thenReturn(null);
        Mockito.when(ctTbl.addNewTblPr()).thenReturn(tPr);
        Mockito.when(tPr.isSetTblInd()).thenReturn(false);
        Mockito.when(tPr.addNewTblInd()).thenReturn(tw);

        StyleUtils.styleTable(table, tableStyle);
    }
}

