import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTP;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTSdtBlock;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTSdtRun;
import org.apache.xmlbeans.XmlCursor;
import org.apache.xmlbeans.XmlObject;

import java.util.List;

public class XWPFParagraphWrappergetSDTs_XWPFParagraphgetCTPFikaTest {

    @Test
    public void testGetSDTs() throws Exception {
        XWPFParagraph paragraph = Mockito.mock(XWPFParagraph.class);
        CTP ctp = Mockito.mock(CTP.class);
        XmlCursor cursor = Mockito.mock(XmlCursor.class);

        Mockito.when(paragraph.getCTP()).thenReturn(ctp);
        Mockito.when(ctp.newCursor()).thenReturn(cursor);
        Mockito.when(cursor.selectPath(Mockito.anyString())).thenReturn(null);
        Mockito.when(cursor.toNextSelection()).thenReturn(false);

        List<XWPFStructuredDocumentTag> result = getSDTs(paragraph);
    }

    private List<XWPFStructuredDocumentTag> getSDTs(XWPFParagraph paragraph) {
        List<XWPFStructuredDocumentTag> sdts = new java.util.ArrayList<>();
        long count = paragraph.getIRuns().stream().filter(r -> r instanceof XWPFStructuredDocumentTag).count();
        if (0 == count) {
            return sdts;
        }

        CTP ctp = paragraph.getCTP();
        XmlCursor c = ctp.newCursor();
        try {
            c.selectPath("child::*");
            while (c.toNextSelection()) {
                XmlObject o = c.getObject();
                if (o instanceof CTSdtBlock) {
                    XWPFStructuredDocumentTag cc = new XWPFStructuredDocumentTag(((CTSdtBlock) (o)), paragraph.getBody());
                    sdts.add(cc);
                }
                if (o instanceof CTSdtRun) {
                    XWPFStructuredDocumentTag cc = new XWPFStructuredDocumentTag(((CTSdtRun) (o)), paragraph.getBody());
                    sdts.add(cc);
                }
            } 
        } finally {
            c.dispose();
        }
        return sdts;
    }
}

