package com.deepoove.poi.xwpf;

import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.junit.jupiter.api.Test;
import java.math.BigInteger;

public class NiceXWPFDocumentaddNewMultiLevelNumberingId_CTDecimalNumbersetValFikaTest {

    @Test
    public void testAddNewMultiLevelNumberingId() throws Exception {
        XWPFDocument document = new XWPFDocument();

        NiceXWPFDocument niceDocument = new NiceXWPFDocument(document);

        NumberingFormat[] numFmts = new NumberingFormat[2];
        numFmts[0] = new NumberingFormat(STNumberFormat.DECIMAL, "1.");
        numFmts[1] = new NumberingFormat(STNumberFormat.DECIMAL, "2.");

        niceDocument.addNewMultiLevelNumberingId(numFmts);
    }

    private static class NiceXWPFDocument {
        private final XWPFDocument document;

        public NiceXWPFDocument(XWPFDocument document) {
            this.document = document;
        }

        public BigInteger addNewMultiLevelNumberingId(NumberingFormat... numFmts) {
            XWPFNumbering numbering = this.getNumbering();
            if (null == numbering) {
                numbering = this.createNumbering();
            }
            XWPFNumberingWrapper numberingWrapper = new XWPFNumberingWrapper(numbering);
            CTAbstractNum cTAbstractNum = CTAbstractNum.Factory.newInstance();
            cTAbstractNum.setAbstractNumId(numberingWrapper.getNextAbstractNumID());

            for (int i = 0; i < numFmts.length; i++) {
                NumberingFormat numFmt = numFmts[i];
                CTLvl cTLvl = cTAbstractNum.addNewLvl();
                CTPPrBase ppr = (cTLvl.isSetPPr()) ? cTLvl.getPPr() : cTLvl.addNewPPr();
                CTInd ind = (ppr.isSetInd()) ? ppr.getInd() : ppr.addNewInd();
                ind.setLeft(BigInteger.valueOf(UnitUtils.cm2Twips(0.74F) * i));
                Enum fmt = STNumberFormat.Enum.forInt(numFmt.getNumFmt());
                String val = numFmt.getLvlText();
                cTLvl.addNewNumFmt().setVal(fmt);
                cTLvl.addNewLvlText().setVal(val);
                cTLvl.addNewStart().setVal(BigInteger.valueOf(1));
                cTLvl.setIlvl(BigInteger.valueOf(i));
                if (fmt == STNumberFormat.BULLET) {
                    cTLvl.addNewLvlJc().setVal(STJc.LEFT);
                    CTRPr addNewRPr = cTLvl.addNewRPr();
                    CTFonts ctFonts = addNewRPr.addNewRFonts();
                    ctFonts.setAscii("Wingdings");
                    ctFonts.setHAnsi("Wingdings");
                    ctFonts.setHint(STHint.DEFAULT);
                }
            }
            XWPFAbstractNum abstractNum = new XWPFAbstractNum(cTAbstractNum);
            BigInteger abstractNumID = numbering.addAbstractNum(abstractNum);
            return numbering.addNum(abstractNumID);
        }

        private XWPFNumbering getNumbering() {
            return document.getNumbering();
        }

        private XWPFNumbering createNumbering() {
            return document.createNumbering();
        }
    }

    private static class NumberingFormat {
        private final int numFmt;
        private final String lvlText;

        public NumberingFormat(int numFmt, String lvlText) {
            this.numFmt = numFmt;
            this.lvlText = lvlText;
        }

        public int getNumFmt() {
            return numFmt;
        }

        public String getLvlText() {
            return lvlText;
        }
    }

    private static class XWPFNumberingWrapper {
        private final XWPFNumbering numbering;

        public XWPFNumberingWrapper(XWPFNumbering numbering) {
            this.numbering = numbering;
        }

        public BigInteger getNextAbstractNumID() {
            return BigInteger.ONE;
        }
    }

    private static class CTAbstractNum {
        public static Factory Factory = new Factory();

        public CTLvl addNewLvl() {
            return new CTLvl();
        }

        public void setAbstractNumId(BigInteger id) {
        }

        public static class Factory {
            public static CTAbstractNum newInstance() {
                return new CTAbstractNum();
            }
        }
    }

    private static class CTLvl {
        public CTPPrBase addNewPPr() {
            return new CTPPrBase();
        }

        public boolean isSetPPr() {
            return false;
        }

        public CTPPrBase getPPr() {
            return null;
        }

        public CTDecimalNumber addNewNumFmt() {
            return new CTDecimalNumber();
        }

        public CTDecimalNumber addNewLvlText() {
