package com.deepoove.poi.util;

import org.apache.poi.xwpf.usermodel.XWPFTable;
import org.junit.jupiter.api.Test;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTbl;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblPr;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblWidth;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.STTblWidth;

import java.math.BigInteger;

import static org.mockito.Mockito.*;

public class StyleUtilsstyleTable_CTTblPrisSetTblIndFikaTest {

    @Test
    public void testStyleTableInvokesIsSetTblInd() {
        XWPFTable table = mock(XWPFTable.class);
        TableStyle tableStyle = mock(TableStyle.class);

        CTTbl ctTbl = mock(CTTbl.class);
        CTTblPr tPr = mock(CTTblPr.class);
        CTTblWidth tw = mock(CTTblWidth.class);

        when(table.getCTTbl()).thenReturn(ctTbl);
        when(ctTbl.getTblPr()).thenReturn(tPr);
        when(tPr.isSetTblInd()).thenReturn(true);
        when(tPr.getTblInd()).thenReturn(tw);

        when(tableStyle.getIndentation()).thenReturn(1.0);
        when(tableStyle.getWidth()).thenReturn(100.0);
        when(tableStyle.getColWidths()).thenReturn(new double[]{50.0, 50.0});
        when(tableStyle.getLeftBorder()).thenReturn(new BorderStyle());
        when(tableStyle.getRightBorder()).thenReturn(new BorderStyle());
        when(tableStyle.getTopBorder()).thenReturn(new BorderStyle());
