package com.deepoove.poi.util;

import org.apache.poi.xwpf.usermodel.XWPFTableCell;
import org.apache.poi.xwpf.usermodel.VerticalAlign;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTc;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

public class StyleUtilsstyleTableCell_CTTcgetTcPrFikaTest {

    @Test
    public void testInvokeGetTcPr() throws Exception {
        XWPFTableCell cell = Mockito.mock(XWPFTableCell.class);
        CellStyle cellStyle = new CellStyle();
        cellStyle.setBackgroundColor("FF0000");

        CTTc ctTc = Mockito.mock(CTTc.class);
        CTTcPr tcPr = Mockito.mock(CTTcPr.class);

        Mockito.when(cell.getCTTc()).thenReturn(ctTc);
        Mockito.when(ctTc.isSetTcPr()).thenReturn(true);
        Mockito.when(ctTc.getTcPr()).thenReturn(tcPr);

        StyleUtils.styleTableCell(cell, cellStyle);
    }

    private static class CellStyle {
        private String backgroundColor;
        private VerticalAlign vertAlign;
        private XWPFShadingPattern shadingPattern;

        public String getBackgroundColor() {
            return backgroundColor;
        }

        public void setBackgroundColor(String backgroundColor) {
            this.backgroundColor = backgroundColor;
        }

        public VerticalAlign getVertAlign() {
            return vertAlign;
        }

        public void setVertAlign(VerticalAlign vertAlign) {
            this.vertAlign = vertAlign;
        }

        public XWPFShadingPattern getShadingPattern() {
            return shadingPattern;
        }
    }

    private static class XWPFShadingPattern {
        private int value;

        public int getValue() {
            return value;
        }
    }
}

