    @Test
    public void testStyleTableCellInvokesSetVerticalAlignment() {
        XWPFTableCell mockCell = Mockito.mock(XWPFTableCell.class);
        CellStyle mockCellStyle = Mockito.mock(CellStyle.class);

        XWPFTableCell.XWPFVertAlign vertAlign = XWPFTableCell.XWPFVertAlign.CENTER;
        Mockito.when(mockCellStyle.getVertAlign()).thenReturn(vertAlign);

