        Mockito.when(chart.getChartSeries()).thenReturn(chartSeries);

        Mockito.when(chartData.getSeriesCount()).thenReturn(0);

        XDDFDataSource<?> categoriesDataSource = Mockito.mock(XDDFDataSource.class);
        XDDFNumericalDataSource<? extends Number> valuesDataSource = 
            Mockito.mock(XDDFNumericalDataSource.class);

        Mockito.when(chartData.addSeries(categoriesDataSource, valuesDataSource))
               .thenReturn(Mockito.mock(XDDFChartData.Series.class));

        XWPFTemplate template = Mockito.mock(XWPFTemplate.class);

        XSSFSheet sheet = Mockito.mock(XSSFSheet.class);
