        Mockito.when(chart.getWorkbook().getSheetAt(0)).thenReturn(sheet);

        com.deepoove.poi.data.ChartMultiSeriesRenderData renderData = 
            Mockito.mock(com.deepoove.poi.data.ChartMultiSeriesRenderData.class);

        List<com.deepoove.poi.data.SeriesRenderData> seriesList = new ArrayList<>();
        com.deepoove.poi.data.SeriesRenderData series1 = Mockito.mock(com.deepoove.poi.data.SeriesRenderData.class);
        Mockito.when(series1.getName()).thenReturn("Series1");
        Mockito.when(series1.getValues()).thenReturn(new Double[]{1.0, 2.0, 3.0});
        seriesList.add(series1);
