import org.junit.jupiter.api.Test;
import java.math.BigInteger;

public class StyleUtilsstyleTableCell_CTTcPrgetShdFikaTest {

    @Test
    public void testStyleTableCellInvokesGetShd() throws Exception {
        XWPFDocument document = new XWPFDocument();
        XWPFTable table = document.createTable(1, 1);
        XWPFTableRow row = table.getRow(0);
        XWPFTableCell cell = row.getCell(0);

        CellStyle cellStyle = new CellStyle();
        cellStyle.setBackgroundColor("FF0000");

        StyleUtils.styleTableCell(cell, cellStyle);

        document.close();
    }

    private static class CellStyle {
        private String backgroundColor;
        private XWPFShadingPattern shadingPattern;
        private STVertAlign vertAlign;

        public String getBackgroundColor() {
            return backgroundColor;
        }

        public void setBackgroundColor(String backgroundColor) {
            this.backgroundColor = backgroundColor;
        }

        public XWPFShadingPattern getShadingPattern() {
            return shadingPattern;
        }

        public void setShadingPattern(XWPFShadingPattern shadingPattern) {
            this.shadingPattern = shadingPattern;
        }

        public STVertAlign getVertAlign() {
            return vertAlign;
        }

        public void setVertAlign(STVertAlign vertAlign) {
            this.vertAlign = vertAlign;
        }
    }

    private static class XWPFShadingPattern {
        private int value;

        public XWPFShadingPattern(int value) {
            this.value = value;
        }

        public int getValue() {
            return value;
        }
    }

    private enum STVertAlign {
        TOP, CENTER, BOTTOM
    }

    private static class STShd {
        public static final STShd CLEAR = new STShd();

        public static class Enum {
            public static STShd forInt(int val) {
                return new STShd();
            }
        }

        public void setVal(STShd shd) {
        }
    }
}

