        CTTc ctTc = cell.getCTTc();
        ctTc.unsetTcPr();

        CellStyle cellStyle = new CellStyle();
        cellStyle.setBackgroundColor("FF0000");

        StyleUtils.styleTableCell(cell, cellStyle);
    }

