            this.shadingPattern = shadingPattern;
        }

        public XWPFVertAlign getVertAlign() {
            return vertAlign;
        }

        public void setVertAlign(XWPFVertAlign vertAlign) {
            this.vertAlign = vertAlign;
        }
    }

    enum XWPFShadingPattern {
        CLEAR(0);

        private final int value;

        XWPFShadingPattern(int value) {
            this.value = value;
        }

        public int getValue() {
            return value;
        }
    }

    enum XWPFVertAlign {
        TOP, CENTER, BOTTOM
    }
}

