package com.deepoove.poi.plugin.table;

import com.deepoove.poi.XWPFTemplate;
import com.deepoove.poi.config.Configure;
import com.deepoove.poi.template.ElementTemplate;
import com.deepoove.poi.template.run.RunTemplate;
import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.apache.poi.xwpf.usermodel.XWPFRun;
import org.apache.poi.xwpf.usermodel.XWPFTable;
import org.apache.poi.xwpf.usermodel.XWPFTableCell;
import org.apache.poi.xwpf.usermodel.XWPFTableRow;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTcPr;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTVMerge;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.STMerge;
import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class LoopRowTableRenderPolicyrender_CTVMergesetValFikaTest {

    @Test
    public void test() throws Exception {
        XWPFDocument document = new XWPFDocument();
        XWPFTable table = document.createTable(2, 1);

        XWPFTableCell firstCell = table.getRow(0).getCell(0);
        XWPFTableCell tagCell = table.getRow(1).getCell(0);
        addRestartVMerge(firstCell);
        addRestartVMerge(tagCell);

        XWPFParagraph paragraph = tagCell.getParagraphs().isEmpty() ? tagCell.addParagraph() : tagCell.getParagraphs().get(0);
        XWPFRun run = paragraph.createRun();
        run.setText("", 0);

        ElementTemplate eleTemplate = createRunTemplate(run, "{{hack}}");
        Configure config = Configure.builder().build();
        XWPFTemplate template = createTemplate(document, config);

        List<Map<String, Object>> data = new ArrayList<Map<String, Object>>();
        data.add(new HashMap<String, Object>());
        data.add(new HashMap<String, Object>());

        Object policy = instantiatePolicy();
        Method render = findRenderMethod(policy.getClass());
        try {
            render.invoke(policy, eleTemplate, data, template);
        } catch (InvocationTargetException e) {
        }
    }

    private static void addRestartVMerge(XWPFTableCell cell) {
        if (cell == null || cell.getCTTc() == null) {
            return;
        }

        CTTcPr tcPr = cell.getCTTc().getTcPr();
        if (tcPr == null) {
            tcPr = cell.getCTTc().addNewTcPr();
        }

        CTVMerge vMerge = tcPr.getVMerge();
        if (vMerge == null) {
            vMerge = tcPr.addNewVMerge();
        }

        vMerge.setVal(STMerge.RESTART);
    }

    private static ElementTemplate createRunTemplate(XWPFRun run, String tag) throws Exception {
        Class<?> clazz = RunTemplate.class;

        try {
            Constructor<?> ctor = clazz.getConstructor(XWPFRun.class, String.class);
            return (ElementTemplate) ctor.newInstance(run, tag);
        } catch (NoSuchMethodException e) {
        }

        try {
            Constructor<?> ctor = clazz.getDeclaredConstructor(XWPFRun.class, String.class);
            ctor.setAccessible(true);
            return (ElementTemplate) ctor.newInstance(run, tag);
        } catch (NoSuchMethodException e) {
        }

        for (Constructor<?> ctor : clazz.getDeclaredConstructors()) {
            Class<?>[] types = ctor.getParameterTypes();
            boolean hasRun = false;
            boolean hasString = false;

            for (Class<?> type : types) {
                if (isRunType(type)) {
                    hasRun = true;
                }
                if (type == String.class) {
                    hasString = true;
                }
            }

            if (hasRun && hasString) {
                Object[] args = new Object[types.length];
                boolean tagUsed = false;

                for (int i = 0; i < types.length; i++) {
                    if (isRunType(types[i])) {
                        args[i] = run;
                    } else if (types[i] == String.class && !tagUsed) {
                        args[i] = tag;
                        tagUsed = true;
                    } else {
                        args[i] = defaultValue(types[i]);
                    }
                }

                try {
                    ctor.setAccessible(true);
                    return (ElementTemplate) ctor.newInstance(args);
                } catch (Exception e) {
                }
            }
        }

        throw new IllegalStateException("Cannot create RunTemplate");
    }

    private static XWPFTemplate createTemplate(XWPFDocument document, Configure config) throws Exception {
        byte[] bytes = toBytes(document);
        Class<?> clazz = XWPFTemplate.class;
        Exception last = null;
        String[] names = new String[] {"create", "compile", "build", "of"};

        for (int i = 0; i < names.length; i++) {
            try {
                Method m = clazz.getMethod(names[i], InputStream.class, Configure.class);
                Object result = m.invoke(null, new ByteArrayInputStream(bytes), config);
                if (result instanceof XWPFTemplate) {
                    return (XWPFTemplate) result;
                }
            } catch (Exception e) {
                last = e;
            }
        }

        for (int i = 0; i < names.length; i++) {
            try {
                Method m = clazz.getMethod(names[i], InputStream.class);
                Object result = m.invoke(null, new ByteArrayInputStream(bytes));
                if (result instanceof XWPFTemplate) {
                    XWPFTemplate template = (XWPFTemplate) result;
                    applyConfig(template, config);
                    return template;
                }
            } catch (Exception e) {
                last = e;
            }
        }

        try {
            Constructor<?> ctor = clazz.getDeclaredConstructor(Configure.class);
            ctor.setAccessible(true);
            Object result = ctor.newInstance(config);
            if (result instanceof XWPFTemplate) {
