package com.deepoove.poi.plugin.table;

import com.deepoove.poi.XWPFTemplate;
import com.deepoove.poi.plugin.table.LoopRowTableRenderPolicy;
import com.deepoove.poi.template.ElementTemplate;
import com.deepoove.poi.template.run.RunTemplate;
import org.apache.poi.xwpf.usermodel.*;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.util.Arrays;
import java.util.List;

public class LoopRowTableRenderPolicyrender_XWPFRunsetTextFikaTest {

    @Test
    public void testRender() throws Exception {
        LoopRowTableRenderPolicy policy = new LoopRowTableRenderPolicy();

        RunTemplate runTemplate = Mockito.mock(RunTemplate.class);
        XWPFRun mockRun = Mockito.mock(XWPFRun.class);
        Mockito.when(runTemplate.getRun()).thenReturn(mockRun);

        XWPFParagraph mockParagraph = Mockito.mock(XWPFParagraph.class);
        Mockito.when(mockRun.getParent()).thenReturn(mockParagraph);

        XWPFTableCell mockCell = Mockito.mock(XWPFTableCell.class);
        Mockito.when(mockParagraph.getBody()).thenReturn(mockCell);

        XWPFTableRow mockRow = Mockito.mock(XWPFTableRow.class);
        Mockito.when(mockCell.getTableRow()).thenReturn(mockRow);

        XWPFTable mockTable = Mockito.mock(XWPFTable.class);
        Mockito.when(mockRow.getTable()).thenReturn(mockTable);

        Mockito.when(TableTools.isInsideTable(mockRun)).thenReturn(true);

        Mockito.when(mockTable.getRow(Mockito.anyInt())).thenReturn(mockRow);
        Mockito.when(mockTable.insertNewTableRow(Mockito.anyInt())).thenReturn(mockRow);

        List<XWPFTableCell> cells = Arrays.asList(mockCell);
        Mockito.when(mockRow.getTableCells()).thenReturn(cells);

        List<XWPFTableCell> tableCells = Arrays.asList(mockCell);
        Mockito.when(mockRow.getTableCells()).thenReturn(tableCells);

        XWPFTemplate mockTemplate = Mockito.mock(XWPFTemplate.class);
        XWPFTemplate.Config mockConfig = Mockito.mock(XWPFTemplate.Config.class);
        Mockito.when(mockTemplate.getConfig()).thenReturn(mockConfig);

        Iterable<String> data = Arrays.asList("item1", "item2");

        policy.render(runTemplate, data, mockTemplate);
    }
}

