            colWidths = UnitUtils.average(Integer.valueOf(width), columnSize);
        } else if (table.getWidthType() == TableWidthType.PCT) {
            int sum = 0;
            colWidths = new int[columnSize];
            for (int i = 0; i < (columnSize - 1); i++) {
