package com.deepoove.poi.util;

import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.apache.poi.xwpf.usermodel.ParagraphAlignment;
import org.apache.poi.xwpf.usermodel.LineSpacingRule;
import org.apache.poi.xwpf.usermodel.XWPFShadingPattern;
import org.apache.poi.xwpf.usermodel.XWPFOnOff;
import com.deepoove.poi.data.style.ParagraphStyle;
import com.deepoove.poi.util.UnitUtils;
import org.junit.jupiter.api.Test;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTP;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTPPr;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTInd;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTPBdr;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTShd;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.STShd;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTOnOff;

import java.math.BigInteger;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class StyleUtilsstylePpr_CTPPrgetWordWrapFikaTest {

    @Test
    public void testStylePpr() throws Exception {
        XWPFParagraph paragraph = mock(XWPFParagraph.class);
        ParagraphStyle style = mock(ParagraphStyle.class);

        CTP ctp = mock(CTP.class);
        CTPPr pr = mock(CTPPr.class);
        CTInd indent = mock(CTInd.class);
        CTPBdr ct = mock(CTPBdr.class);
        CTOnOff ctWW = mock(CTOnOff.class);

        when(paragraph.getCTP()).thenReturn(ctp);
        when(ctp.isSetPPr()).thenReturn(true);
        when(ctp.getPPr()).thenReturn(pr);
        when(pr.isSetInd()).thenReturn(true);
        when(pr.getInd()).thenReturn(indent);
        when(pr.isSetPBdr()).thenReturn(true);
        when(pr.getPBdr()).thenReturn(ct);

        when(style.getAllowWordBreak()).thenReturn(true);
        when(pr.isSetWordWrap()).thenReturn(true);
        when(pr.getWordWrap()).thenReturn(ctWW);

        StyleUtils.stylePpr(paragraph, style);
    }
}

