import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTOnOff;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.math.BigInteger;

public class StyleUtilsstylePpr_CTPPrgetKeepLinesFikaTest {

    @Test
    public void testStylePpr() {
        XWPFParagraph paragraph = Mockito.mock(XWPFParagraph.class);
        ParagraphStyle style = new ParagraphStyle();

        CTP mockCtp = Mockito.mock(CTP.class);
        CTPPr mockPr = Mockito.mock(CTPPr.class);
        CTOnOff mockKeepLines = Mockito.mock(CTOnOff.class);

        Mockito.when(paragraph.getCTP()).thenReturn(mockCtp);
        Mockito.when(mockCtp.isSetPPr()).thenReturn(true);
        Mockito.when(mockCtp.getPPr()).thenReturn(mockPr);
        Mockito.when(mockPr.isSetKeepLines()).thenReturn(true);
        Mockito.when(mockPr.getKeepLines()).thenReturn(mockKeepLines);

        style.setKeepLines(true);

        StyleUtils.stylePpr(paragraph, style);
    }
}

