            XWPFParagraph paragraph = document.getParagraphArray(0);

            // The static field initializations will execute when class is loaded,
            // which happens when we reference the class or create an instance
            // We'll create a wrapper instance to ensure class is fully initialized
            XWPFParagraphWrapper wrapper = new XWPFParagraphWrapper(paragraph);

            // The QName constructors are called during static initialization,
            // so simply loading the class is sufficient to invoke them
        }
    }
}

