@Override
public void render(ElementTemplate eleTemplate, Object data, XWPFTemplate template) {
    T model = null;
    try {
        model = cast(data);
    } catch (Exception e) {
        throw new RenderException("Error Render Data format for template: " + eleTemplate.getSource(), e);
    }
    RenderContext<T> context = new RenderContext<T>(eleTemplate, model, template);
    try {
        // validate
        if (!validate(model)) // PATH: Test should invoke the next AbstractRenderPolicy.postValidError(...) [step in execution path]
        {
            postValidError(context);
            return;
        }
        // do render
        beforeRender(context);
        doRender(context);
        afterRender(context);
    } catch (Exception e) {
        reThrowException(context, e);
    }
}

protected void postValidError(RenderContext<T> context) {
    ValidErrorHandler errorHandler = context.getConfig().getValidErrorHandler();
    // PATH: Test should invoke the next ClassUtils.getSimpleName(...) [step in execution path]
    logger.info("The data [{}] of the template {} is illegal, will apply error handler [{}]", context.getData(), context.getTagSource(), ClassUtils.getSimpleName(errorHandler.getClass()));
    errorHandler.handler(context);
}

