        PictureRenderPolicy policy = new PictureRenderPolicy();

        RenderContext<PictureRenderData> context = createRenderContext();

        try {
            policy.reThrowException(context, new RuntimeException("Test exception"));
        } catch (Exception e) {
            // Ignore - we only care about execution path
        }
    }

    private RenderContext<PictureRenderData> createRenderContext() {
        PictureRenderData data = new PictureRenderData();
        data.altMeta("Alternative text");

        XWPFRun run = new XWPFRun(null, null) {
            @Override
            public void setText(String text, int pos) {
                // Real implementation will be called
                super.setText(text, pos);
            }
        };

        return new RenderContext<PictureRenderData>() {
            @Override
            public String getEleTemplate() {
                return "template";
            }

            @Override
            public PictureRenderData getData() {
                return data;
            }

            @Override
            public XWPFRun getRun() {
                return run;
            }
        };
    }
}

