private static final Logger LOG = LoggerFactory.getLogger(RunningRunBody.class);
static QNameSet qname = QNameSet.forArray(new QName[]{ new QName("http://schemas.openxmlformats.org/wordprocessingml/2006/main", "br"), new QName("http://schemas.openxmlformats.org/wordprocessingml/2006/main", "t"), new QName("http://schemas.openxmlformats.org/wordprocessingml/2006/main", "cr"), new QName("http://schemas.openxmlformats.org/wordprocessingml/2006/main", "tab") });

