import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class SingleSeriesChartTemplateRenderPolicy_AbstractChartTemplateRenderPolicyplot_CTAxDataSourceunsetNumRefFikaTest {

    @Test
    public void testPlotInvokesUnsetNumRef() throws Exception {
        // Create a real CTAxDataSource with NumRef set
        CTAxDataSource axDataSource = CTAxDataSource.Factory.newInstance();
        CTNumRef numRef = CTNumRef.Factory.newInstance();
        CTNumData numData = CTNumData.Factory.newInstance();
        numRef.setNumCache(numData);
        axDataSource.setNumRef(numRef);

        // Create a mock series that returns the real CTAxDataSource
        XDDFChartData.Series mockSeries = mock(XDDFChartData.Series.class);
        when(mockSeries.getCategoryData()).thenReturn(mock(XDDFDataSource.class));
        when(mockSeries.getValuesData()).thenReturn(mock(XDDFNumericalDataSource.class));

        // Use reflection to make getAxDSMethod return our real CTAxDataSource
        when(mockSeries.getClass().getDeclaredMethod("getAxDS")).thenReturn(
            Series.class.getDeclaredMethod("getAxDS")
        );

        // Create a mock chart data with the series
        XDDFChartData mockChartData = mock(XDDFChartData.class);
        when(mockChartData.getSeries()).thenReturn(Collections.singletonList(mockSeries));

        // Create a mock chart
        XWPFChart mockChart = mock(XWPFChart.class);
        org.apache.poi.xssf.usermodel.XSSFWorkbook mockWorkbook = mock(org.apache.poi.xssf.usermodel.XSSFWorkbook.class);
        org.apache.poi.xssf.usermodel.XSSFSheet mockSheet = mock(org.apache.poi.xssf.usermodel.XSSFSheet.class);
        when(mockChart.getWorkbook()).thenReturn(mockWorkbook);
        when(mockWorkbook.getSheetAt(0)).thenReturn(mockSheet);

        // Mock the XDDFChart class to return the fillSheet method
        try (MockedConstruction<XDDFChart> mocked = Mockito.mockConstruction(XDDFChart.class,
                (mock, context) -> {
                    Method fillSheetMethod = XDDFChart.class.getDeclaredMethod("fillSheet",
                            org.apache.poi.xssf.usermodel.XSSFSheet.class,
                            XDDFDataSource.class,
                            XDDFNumericalDataSource.class);
                    fillSheetMethod.setAccessible(true);
                })) {

            // Create an instance of the class under test
            AbstractChartTemplateRenderPolicy policy = new AbstractChartTemplateRenderPolicy() {
                @Override
                protected void plot(XWPFChart chart, XDDFChartData data) throws Exception {
                    super.plot(chart, data);
                }
            };

            // Invoke the plot method which should trigger unsetNumRef
            policy.plot(mockChart, mockChartData);
        }
    }

    // Helper class to provide the getAxDS method via reflection
    private static class Series {
        @SuppressWarnings("unused")
        public CTAxDataSource getAxDS() {
            CTAxDataSource axDataSource = CTAxDataSource.Factory.newInstance();
            CTNumRef numRef = CTNumRef.Factory.newInstance();
            CTNumData numData = CTNumData.Factory.newInstance();
            numRef.setNumCache(numData);
            axDataSource.setNumRef(numRef);
            return axDataSource;
        }
    }

    // Minimal abstract class to make the test compile
    private abstract static class AbstractChartTemplateRenderPolicy {
        @SuppressWarnings("deprecation")
        protected void plot(XWPFChart chart, XDDFChartData data) throws Exception {
            org.apache.poi.xssf.usermodel.XSSFSheet sheet = chart.getWorkbook().getSheetAt(0);
            Method method = XDDFChart.class.getDeclaredMethod("fillSheet", 
                    org.apache.poi.xssf.usermodel.XSSFSheet.class, 
                    XDDFDataSource.class, 
                    XDDFNumericalDataSource.class);
            method.setAccessible(true);
            for (XDDFChartData.Series series : data.getSeries()) {
                boolean numeric = series.getCategoryData().isNumeric();
                if (!numeric) {
                    Method getAxDSMethod = series.getClass().getDeclaredMethod("getAxDS");
                    getAxDSMethod.setAccessible(true);
                    CTAxDataSource axDataSource = ((CTAxDataSource) (getAxDSMethod.invoke(series)));
                    if (axDataSource.isSetNumRef()) {
                        axDataSource.unsetNumRef();
                    }
                    if (axDataSource.isSetNumLit()) {
                        axDataSource.unsetNumLit();
                    }
                }
                series.plot();
                method.invoke(chart, sheet, series.getCategoryData(), series.getValuesData());
            }
        }
    }
}

