    this.sdt = parent;
    if (sdtRun == null) {
        return;
    }
    XmlCursor cursor = sdtRun.newCursor();
    cursor.selectPath("./*");
    while (cursor.toNextSelection()) {
        XmlObject o = cursor.getObject();
        if (o instanceof CTR) {
