import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import org.openxmlformats.schemas.drawingml.x2006.chart.CTAxDataSource;
import org.openxmlformats.schemas.drawingml.x2006.chart.CTChart;
import org.openxmlformats.schemas.drawingml.x2006.chart.CTPlotArea;
import org.openxmlformats.schemas.drawingml.x2006.chart.CTNumDataSource;
import org.openxmlformats.schemas.drawingml.x2006.chart.CTNumRef;
import org.openxmlformats.schemas.drawingml.x2006.chart.CTNumData;

import java.lang.reflect.Method;
import java.util.Collections;

public class SingleSeriesChartTemplateRenderPolicy_AbstractChartTemplateRenderPolicyplot_CTAxDataSourceunsetNumLitFikaTest {

    @Test
    public void testPlotInvokesUnsetNumLit() throws Exception {
        XWPFChart chart = Mockito.mock(XWPFChart.class);
        XDDFChartData data = Mockito.mock(XDDFChartData.class);
        XDDFChartData.Series series = Mockito.mock(XDDFChartData.Series.class);
        XDDFDataSource<?> categoryData = Mockito.mock(XDDFDataSource.class);
        XDDFNumericalDataSource<?> valuesData = Mockito.mock(XDDFNumericalDataSource.class);

        org.apache.poi.xssf.usermodel.XSSFSheet sheet = Mockito.mock(org.apache.poi.xssf.usermodel.XSSFSheet.class);
        org.apache.poi.xssf.usermodel.XSSFWorkbook workbook = Mockito.mock(org.apache.poi.xssf.usermodel.XSSFWorkbook.class);

        Mockito.when(chart.getWorkbook()).thenReturn(workbook);
        Mockito.when(workbook.getSheetAt(0)).thenReturn(sheet);
        Mockito.when(data.getSeries()).thenReturn(Collections.singletonList(series));
        Mockito.when(series.getCategoryData()).thenReturn(categoryData);
        Mockito.when(series.getValuesData()).thenReturn(valuesData);
        Mockito.when(categoryData.isNumeric()).thenReturn(false);

        CTAxDataSource axDataSource = CTAxDataSource.Factory.newInstance();
        CTNumRef numRef = axDataSource.addNewNumRef();
        CTNumData numData = CTNumData.Factory.newInstance();
        numRef.setNumCache(numData);

        CTNumLit numLit = axDataSource.addNewNumLit();
        numLit.addNewPtCount().setVal(0);

        Class<?> seriesClass = createSeriesClassWithAxDS(axDataSource);
        Mockito.when(series.getClass()).thenReturn((Class) seriesClass);

        XDDFChart xddfChart = Mockito.mock(XDDFChart.class);
        Method fillSheetMethod = XDDFChart.class.getDeclaredMethod("fillSheet", 
            org.apache.poi.xssf.usermodel.XSSFSheet.class, 
            XDDFDataSource.class, 
            XDDFNumericalDataSource.class);
        fillSheetMethod.setAccessible(true);

        Mockito.doNothing().when(xddfChart).fillSheet(Mockito.any(), Mockito.any(), Mockito.any());
        Mockito.doNothing().when(series).plot();

        Method plotMethod = getClass().getSuperclass().getDeclaredMethod("plot", XWPFChart.class, XDDFChartData.class);
        plotMethod.setAccessible(true);

        plotMethod.invoke(new TestablePolicy(), chart, data);
    }

    private Class<?> createSeriesClassWithAxDS(CTAxDataSource axDataSource) {
        return new Object() {
            public CTAxDataSource getAxDS() {
                return axDataSource;
            }
        }.getClass();
    }

    private class TestablePolicy {
        @SuppressWarnings("deprecation")
        protected void plot(XWPFChart chart, XDDFChartData data) throws Exception {
            org.apache.poi.xssf.usermodel.XSSFSheet sheet = chart.getWorkbook().getSheetAt(0);
            Method method = XDDFChart.class.getDeclaredMethod("fillSheet", 
                org.apache.poi.xssf.usermodel.XSSFSheet.class, 
                XDDFDataSource.class, 
                XDDFNumericalDataSource.class);
            method.setAccessible(true);
            for (XDDFChartData.Series series : data.getSeries()) {
                boolean numeric = series.getCategoryData().isNumeric();
                if (!numeric) {
                    Method getAxDSMethod = series.getClass().getDeclaredMethod("getAxDS");
                    getAxDSMethod.setAccessible(true);
                    CTAxDataSource axDataSource = ((CTAxDataSource) (getAxDSMethod.invoke(series)));
                    if (axDataSource.isSetNumRef()) {
                        axDataSource.unsetNumRef();
                    }
                    if (axDataSource.isSetNumLit()) {
                        axDataSource.unsetNumLit();
                    }
                }
                series.plot();
                method.invoke(chart, sheet, series.getCategoryData(), series.getValuesData());
            }
        }
    }
}

