class HelpercreateBookmark_XWPFRungetParentFikaTest {

    @Test
    void testCreateBookmark() throws Exception {
        XWPFRun textRun = Mockito.mock(XWPFRun.class);
        XWPFParagraph paragraph = Mockito.mock(XWPFParagraph.class);

        Mockito.when(textRun.getParent()).thenReturn(paragraph);

        // Invoke the private method via reflection
        java.lang.reflect.Method method = Helper.class.getDeclaredMethod(
            "createBookmark", 
            XWPFRun.class, 
            String.class
        );
        method.setAccessible(true);
        method.invoke(null, textRun, "testBookmark");
    }

    // Helper class to access the private method
    private static class Helper {
        // This mirrors the original method structure
        private static void createBookmark(XWPFRun textRun, String name) {
            XWPFParagraphWrapper wapper = 
                new XWPFParagraphWrapper(((XWPFParagraph) (textRun.getParent())));
            CTBookmark bookmarkStart = wapper.insertNewBookmark(textRun);
            bookmarkStart.setName(name);
        }
    }

    // Minimal required supporting classes
    private static class XWPFParagraphWrapper {
        XWPFParagraphWrapper(XWPFParagraph paragraph) {}
        CTBookmark insertNewBookmark(XWPFRun run) {
            return new CTBookmark();
        }
    }

    private static class CTBookmark {
        void setName(String name) {}
    }
}

