public XWPFParagraph insertNewParagraph(final XmlCursor cursor) {
    if (// PATH: Test should invoke the next XWPFStructuredDocumentTagContent.isCursorInBlockContent(...) [step in execution path]
    !isCursorInBlockContent(cursor)) {
        return null;
    }
    String uri = CTP.type.getName().getNamespaceURI();
    String localPart = "p";
    cursor.beginElement(localPart, uri);
    cursor.toParent();
    CTP p = ((CTP) (cursor.getObject()));
    XWPFParagraph newP = new XWPFParagraph(p, this);
    XmlObject o = null;
    while ((!(o instanceof CTP)) && cursor.toPrevSibling()) {
        o = cursor.getObject();
    } 
    if ((!(o instanceof CTP)) || (o == p)) {
        paragraphs.add(0, newP);
    } else {
        int pos = paragraphs.indexOf(getParagraph(((CTP) (o)))) + 1;
        paragraphs.add(pos, newP);
    }
    int i = 0;
    XmlCursor p2 = p.newCursor();
    cursor.toCursor(p2);
    p2.dispose();
    while (cursor.toPrevSibling()) {
        o = cursor.getObject();
        if ((o instanceof CTP) || (o instanceof CTTbl)) {
            i++;
        }
    } 
    sdtElements.add(i, newP);
    p2 = p.newCursor();
    cursor.toCursor(p2);
    p2.dispose();
    cursor.toEndToken();
    return newP;
}

private boolean isCursorInBlockContent(XmlCursor cursor) {
    XmlCursor verify = cursor.newCursor();
    verify.toParent();
    // PATH: Test should invoke the next XmlCursor.getObject(...) [step in execution path]
    boolean result = verify.getObject() == this.sdtContentBlock;
    verify.dispose();
    return result;
}

