    xmlText = xmlText.replaceAll("<w:p><w:POITL>", "").replaceAll("<w:p(\\s[A-Za-z0-9:\\s=\"]*)?><w:POITL>", "").replaceAll("</w:POITL></w:p>", "");
    return xmlText;
}

