        // Create two real XWPFDocument instances
        XWPFDocument sourceDoc = new XWPFDocument();
        XWPFDocument mergeDoc = new XWPFDocument();

        // Create ByteArrayOutputStream to write documents
        ByteArrayOutputStream sourceOut = new ByteArrayOutputStream();
        ByteArrayOutputStream mergeOut = new ByteArrayOutputStream();

        sourceDoc.write(sourceOut);
        mergeDoc.write(mergeOut);

        // Close the original documents
        sourceDoc.close();
        mergeDoc.close();

        // Create new documents from the byte arrays
        ByteArrayInputStream sourceIn = new ByteArrayInputStream(sourceOut.toByteArray());
        ByteArrayInputStream mergeIn = new ByteArrayInputStream(mergeOut.toByteArray());

