        Class<?> niceXWPFDocumentClass = Class.forName("com.deepoove.poi.xwpf.NiceXWPFDocument");

        // Create a mock that extends NiceXWPFDocument
        Object mockNiceDoc = Mockito.mock(niceXWPFDocumentClass, 
            Mockito.withSettings()
                .useConstructor(doc)
                .defaultAnswer(Mockito.CALLS_REAL_METHODS));

        // Get the CTDocument1 from the XWPFDocument
