        Object ctDocument = getDocumentMethod.invoke(doc);

        // Create a mock XmlCursor that will actually call getAllNamespaces
        XmlCursor mockCursor = Mockito.mock(XmlCursor.class, Mockito.CALLS_REAL_METHODS);

        // When getAllNamespaces is called, it should populate the map
        Mockito.doAnswer(invocation -> {
            Map<String, String> map = invocation.getArgument(0);
            map.put("test", "namespace");
            return null;
        }).when(mockCursor).getAllNamespaces(Mockito.any(Map.class));

        // Mock the CTDocument1's newCursor method to return our mock cursor
        Object mockCtDocument = Mockito.mock(ctDocument.getClass());
        Mockito.when(mockCtDocument.newCursor()).thenReturn(mockCursor);

        // Mock the getDocument method to return our mocked CTDocument1
        Mockito.when(((org.mockito.Mockito) mockNiceDoc).getDocument()).thenReturn(mockCtDocument);

        return mockNiceDoc;
    }

    private java.lang.reflect.Method findMergeNamespacesMethod() throws Exception {
        Class<?> clazz = Class.forName("com.deepoove.poi.xwpf.XmlXWPFDocumentMerge");
        java.lang.reflect.Method[] methods = clazz.getDeclaredMethods();

