public void doRender(ChartTemplate eleTemplate, ChartSingleSeriesRenderData data, XWPFTemplate template) throws Exception // PATH: Test should invoke the next AbstractChartTemplateRenderPolicy.setTitle(...) [step in execution path]
{
    XWPFChart chart = eleTemplate.getChart();
    XDDFChartData pie = ChartUtils.getChartSeries(chart).get(0);
    SeriesRenderData seriesDatas = data.getSeriesData();
    XDDFDataSource<?> categoriesData = null;
    if (pie instanceof XDDFScatterChartData) {
        categoriesData = createNumbericalDataSource(chart, toNumberArray(data.getCategories()), 0);
    } else {
        categoriesData = createStringDataSource(chart, data.getCategories(), 0);
    }
    XDDFNumericalDataSource<? extends Number> valuesData = createNumbericalDataSource(chart, seriesDatas.getValues(), 1);
    XDDFChartData.Series currentSeries = pie.getSeries(0);
    currentSeries.replaceData(categoriesData, valuesData);
    currentSeries.setTitle(seriesDatas.getName(), chart.setSheetTitle(seriesDatas.getName(), 1));
    updateCTTable(chart.getWorkbook().getSheetAt(0), Arrays.asList(seriesDatas));
    plot(chart, pie);
    setTitle(chart, data.getChartTitle());
    setAxisTitle(chart, data.getxAxisTitle(), data.getyAxisTitle());
}

protected void setTitle(XWPFChart chart, String title) {
    if ((null == title) && chart.getCTChart().isSetTitle()) {
        chart.getCTChart().unsetTitle();
        return;
    }
    CTTitle ctTitle = chart.getCTChart().getTitle();
    // PATH: Test should invoke the next AbstractChartTemplateRenderPolicy.setCTTitle(...) [step in execution path]
    boolean isSet = setCTTitle(ctTitle, title);
    if (!isSet) {
        chart.setTitleText(title);
        chart.setTitleOverlay(false);
    }
}

private boolean setCTTitle(CTTitle ctTitle, String title) {
    boolean isSet = false;
    if (null != ctTitle) {
        if (!ctTitle.isSetTx()) {
            ctTitle.addNewTx();
        }
        CTTx tx = ctTitle.getTx();
        if (tx.isSetStrRef()) // PATH: Test should invoke the next CTTx.unsetStrRef(...) [step in execution path]
        {
            tx.unsetStrRef();
        }
        if (!tx.isSetRich()) {
            tx.addNewRich();
        }
        CTTextBody body = tx.getRich();
        if (body.sizeOfPArray() > 0) {
            // remove all but first paragraph
            for (int i = body.sizeOfPArray() - 1; i > 0; i--) {
                body.removeP(i);
            }
            CTTextParagraph pArray = body.getPArray(0);
            if (pArray.sizeOfRArray() > 0) {
                for (int i = pArray.sizeOfRArray() - 1; i > 0; i--) {
                    pArray.removeR(i);
                }
                CTRegularTextRun rArray = pArray.getRArray(0);
                rArray.setT(title);
                isSet = true;
            }
        }
    }
    return isSet;
}

