        XWPFNumberingWrapper wrapperMerge = Mockito.mock(XWPFNumberingWrapper.class);
        XWPFNum mockNum = Mockito.mock(XWPFNum.class);
        CTNum mockCTNum = Mockito.mock(CTNum.class);

        Mockito.when(mockNum.getCTNum()).thenReturn(mockCTNum);
        Mockito.when(mockCTNum.getNumId()).thenReturn(BigInteger.ONE);
        Mockito.when(mockCTNum.getAbstractNumId()).thenReturn(Mockito.mock(org.openxmlformats.schemas.wordprocessingml.x2006.main.CTDecimalNumber.class));
        Mockito.when(mockCTNum.getAbstractNumId().getVal()).thenReturn(BigInteger.ONE);

