        Mockito.when(sourceDoc.getNumbering()).thenReturn(null);
        Mockito.when(sourceDoc.createNumbering()).thenReturn(sourceNumbering);

        XWPFNumberingWrapper sourceWrapper = Mockito.mock(XWPFNumberingWrapper.class);
        Mockito.when(sourceWrapper.getNextAbstractNumID()).thenReturn(BigInteger.valueOf(1000L));

        XWPFAbstractNum mockAbstractNum = Mockito.mock(XWPFAbstractNum.class);
        CTAbstractNum mockCTAbstractNum = Mockito.mock(CTAbstractNum.class);
        Mockito.when(mockAbstractNum.getCTAbstractNum()).thenReturn(mockCTAbstractNum);
        Mockito.when(mockCTAbstractNum.isSetTmpl()).thenReturn(true);
        Mockito.when(mergedNumbering.getAbstractNum(Mockito.any(BigInteger.class))).thenReturn(mockAbstractNum);

        Mockito.when(sourceNumbering.addAbstractNum(Mockito.any(XWPFAbstractNum.class))).thenReturn(BigInteger.ONE);
        Mockito.when(sourceNumbering.addNum(Mockito.any(BigInteger.class))).thenReturn(BigInteger.TEN);

        mergeInstance.mergeNumbering(sourceDoc, mergedDoc);
    }
}

